test('onglet : mêmes filtres/conditions/variables, élections et toutes les commandes intactes',()=>{const before=parse(at(base,'plateau-organisations-quetes.js')),after=parse(code('plateau-organisations-quetes.js')),fn=t=>t.body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='renderOngletOrgas'),a=fn(before),b=fn(after);assert.deepEqual(strip(a.body.body.slice(0,2)),strip(b.body.body.slice(0,2)));const callback=n=>{let result;walk(n,x=>{if(x.type==='CallExpression'&&x.callee.object?.name==='mesOrgas'&&x.callee.property?.name==='map')result=x.arguments[0];});return result;};const ca=callback(a),cb=callback(b);assert.ok(ca&&cb);for(const name of ['def','estChef','monMembre','demandesCount','avatarHtml']){const get=n=>n.body.body.find(x=>x.type==='VariableDeclaration'&&x.declarations[0].id.name===name);assert.deepEqual(strip(get(ca)),strip(get(cb)));}const conditions=n=>{const out=[];walk(n,x=>{if(x.type==='ConditionalExpression')out.push(strip(x.test));});return out;};assert.deepEqual(conditions(ca),conditions(cb));for(const t of [before,after])t.body=t.body.filter(n=>n!==fn(t));assert.deepEqual(strip(after),strip(before));assert.equal(execFileSync('git',['diff','--name-only',base,...(proof?[proof.codeCommit]:[]),'--','api','migrations','supabase','supabase.js','auth.js','data.js','forum.js','images','plateau-core.js','plateau-politique.js','style.css','i18n/plateau-init.js'],{cwd:root,encoding:'utf8'}),'');});
