test('onglet : quatorze français exacts, neuf langues, quinze clés réutilisées, variables et références i18next',async()=>{const r=resources(),engine=require('../../i18n/i18next.min.js').createInstance();await engine.init({resources:r,fallbackLng:'fr',lng:'fr',interpolation:{escapeValue:false}});assert.equal(manifest.rows.length,14);assert.equal(manifest.reusedKeys.length,15);assert.deepEqual(r.fr.translation.organizationPanel,Object.fromEntries(manifest.rows));const tokens=s=>[...s.matchAll(/\{\{([^}]+)\}\}/g)].map(x=>x[1]).sort();for(const [lang,res]of Object.entries(r)){for(const [key,fr]of manifest.rows){const text=res.translation.organizationPanel[key];assert.ok(text?.trim());if(lang!=='fr'&&!(lang==='en'&&key==='actions'))assert.notEqual(text,fr);assert.deepEqual(tokens(text),tokens(fr));const resolved=engine.t('organizationPanel.'+key,{lng:lang,values:{count:2}});assert.ok(!resolved.includes('$t(')&&!resolved.includes('{{'));}for(const key of manifest.reusedKeys){const [ns,id]=key.split('.');assert.ok(res.translation[ns][id]);}if(lang!=='fr'){assert.ok(engine.t('organizationPanel.emptyHelp',{lng:lang}).includes(engine.t('orderVariants.local_manage',{lng:lang})));assert.ok(engine.t('organizationPanel.memberCount',{lng:lang,values:{count:2}}).includes(engine.t('sovarkaPartis.secMembers',{lng:lang})));}}assert.equal(engine.t('organizationPanel.memberCount',{lng:'fr',values:{count:2}}),'2 membres');assert.ok(read('plateau.html').indexOf('organization-panel-resources.js')<read('plateau.html').indexOf('i18n/plateau-init.js'));});
